mapper.select:
SELECT b.* FROM booking b
JOIN course_schedule s ON s.id = b.schedule_id
WHERE b.status = 'booked' AND s.end_time < #{now}

SELECT b.* FROM booking b
JOIN course_schedule s ON s.id = b.schedule_id
WHERE b.user_id = #{userId} AND b.store_id = #{storeId}
  AND b.status = 'booked'
  AND s.start_time >= #{from} AND s.start_time <= #{to}
ORDER BY s.start_time LIMIT 1
